/**
 * Precompile the dataset schema into a plain JavaScript validator.
 *
 * Ajv's normal path builds its validator with `new Function`, which the viewer's
 * Content-Security-Policy forbids — and rightly: a page that renders evidence has
 * no business evaluating strings as code. Precompiling keeps real schema
 * validation and needs no eval at run time.
 *
 * The output is committed and checked, in the same way the Python side commits
 * its generated schema: a generated file that nobody diffs is a generated file
 * that silently stops matching its source.
 *
 *   node scripts/compile-schema.mjs           # write
 *   node scripts/compile-schema.mjs --check   # fail if the committed file is stale
 */

import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import process from 'node:process';

import Ajv2020 from 'ajv/dist/2020.js';
import standaloneCode from 'ajv/dist/standalone/index.js';

const root = process.cwd();
const schemaPath = resolve(root, 'src/data/viewer-dataset.schema.json');
const outputPath = resolve(root, 'src/data/validate-dataset.js');

const schema = JSON.parse(readFileSync(schemaPath, 'utf-8'));

// `strict: false` because the schema is generated by pydantic and carries
// annotation keywords Ajv does not recognise. `allErrors` because one problem at
// a time turns a malformed export into an afternoon.
const ajv = new Ajv2020({
  strict: false,
  allErrors: true,
  allowUnionTypes: true,
  code: { source: true, esm: true, lines: true },
});

const validate = ajv.compile(schema);
const banner = `// GENERATED by scripts/compile-schema.mjs from src/data/viewer-dataset.schema.json.
// Do not edit. Regenerate with \`npm run schema:compile\` and review the diff.
`;
const generated = banner + standaloneCode(ajv, validate);

if (process.argv.includes('--check')) {
  const committed = readFileSync(outputPath, 'utf-8');
  if (committed !== generated) {
    process.stderr.write(
      `${outputPath} disagrees with the schema it was generated from. ` +
        'Regenerate it with `npm run schema:compile` and review the diff.\n',
    );
    process.exit(1);
  }
  process.stdout.write('the compiled validator matches the schema\n');
} else {
  writeFileSync(outputPath, generated, 'utf-8');
  process.stdout.write(`wrote ${outputPath}\n`);
}
